python - <<'EOF'
from catalog.service import Catalog
c = Catalog(); c.create("A","x"); c.create("B","y"); dump = c.export()
d = Catalog(); d.create("Z","z"); d.delete("1")
try: d.import_(dump); print("BUG: no collision error")
except ValueError as e: print("collision ok:", e)
d = Catalog(); d.import_(dump); print("next create id after import:", d.create("C","z"))
EOF

